/// Execute the exact generic ManagedAny cleanup instance. Core seals the
/// parameter Drop immediately before a guaranteed checked i32 trap; symbolic
/// execution records the trap and then marks the call path terminal. The
/// structurally present MIR return is unreachable under that receipt and is
/// never exposed to the caller as a normal i32 value.
fn eval_materialized_managed_any_trap_cleanup_call(
    function: &MirFunction,
    program: &MirProgram,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    state: &mut SymbolicState,
    result: &Option<MirValueId>,
    callee: &crate::core::ir::ResolvedCallee,
    type_arguments: &[crate::core::ir::ResolvedTypeId],
    arguments: &[MirValueId],
    effect_receipts: &[crate::core::mir::types::MirCallEffectContract],
    variant_call_contract: Option<&crate::core::mir::types::MirVariantCallAbiContract>,
    instance: &crate::core::mir::MirInstance,
    trap_kind: crate::core::mir::MirManagedAnyTrapKind,
) -> Result<(), String> {
    let crate::core::ir::ResolvedCallee::Function(target_owner) = callee else {
        return Err(
            "ManagedAny trap-cleanup call must target a canonical function instance".into(),
        );
    };
    let target = program.functions().get(target_owner).ok_or_else(|| {
        format!(
            "ManagedAny trap-cleanup target '{}' is absent from canonical MIR",
            target_owner.0
        )
    })?;
    if instance.function != *target_owner
        || !matches!(
            &instance.contract,
            crate::core::mir::MirGenericInstanceContract::ManagedAnyTrapCleanup { trap }
                if *trap == trap_kind
        )
    {
        return Err("ManagedAny trap-cleanup call and instance receipt disagree".into());
    }
    validate_managed_any_trap_cleanup_call_boundary(
        function,
        program,
        result.as_ref(),
        callee,
        type_arguments,
        arguments,
        effect_receipts,
        variant_call_contract,
    )?;
    let canonical_any = catalog.validate_managed_any_identity_source_argument(type_arguments)?;
    let [argument] = arguments else {
        return Err("ManagedAny trap-cleanup call must pass exactly one source owner".into());
    };
    let [parameter] = target.parameters.as_slice() else {
        return Err("ManagedAny trap-cleanup callee must have exactly one parameter".into());
    };
    if instruction_value_type(function, argument, "ManagedAny trap-cleanup call argument")?
        != canonical_any
        || instruction_value_type(target, parameter, "ManagedAny trap-cleanup parameter")?
            != canonical_any
    {
        return Err("ManagedAny trap-cleanup parameter is outside the canonical owner ABI".into());
    }
    catalog.validate_glue(&canonical_any, MirGlueOperation::MoveOut)?;
    let value = state.values.get(argument).cloned().ok_or_else(|| {
        format!(
            "ManagedAny trap-cleanup source '{}' is unavailable",
            argument
        )
    })?;
    if !symbolic_matches_type(catalog, &canonical_any, &value) {
        return Err("ManagedAny trap-cleanup source has the wrong symbolic owner shape".into());
    }
    let result = result.as_ref().ok_or_else(|| {
        "ManagedAny trap-cleanup call has no materialized i32 result identity".to_string()
    })?;
    if !catalog.get(&target.result).is_some_and(|descriptor| {
        descriptor.kind == MirTypeKind::Primitive(crate::core::PrimitiveType::I32)
    }) || instruction_value_type(function, result, "ManagedAny trap-cleanup call result")?
        != target.result
    {
        return Err("ManagedAny trap-cleanup call result is outside the canonical i32 ABI".into());
    }

    let caller_constraints = state.constraints.clone();
    let mut target_state = SymbolicState {
        float_domain: state.float_domain,
        callable_entry_values: None,
        callable_entry_constraints: None,
        values: BTreeMap::from([(parameter.clone(), value)]),
        constraints: caller_constraints,
        traps: Vec::new(),
        list_shapes: BTreeMap::new(),
        known_ints: BTreeMap::new(),
        known_strings: BTreeMap::new(),
        ffi_checks: Vec::new(),
        normal_path_terminated: false,
    };
    let mut returns = Vec::new();
    let mut traps = Vec::new();
    explore_block(
        target,
        program,
        catalog,
        &mut target_state,
        &target.entry,
        &mut BTreeSet::new(),
        &mut returns,
        &mut traps,
    )?;
    let [returned] = returns.as_slice() else {
        return Err(
            "ManagedAny trap-cleanup callee must have its one sealed structural return edge".into(),
        );
    };
    // `add_definedness` records every predicate's trap edge before the outer
    // verifier solver decides reachability. For the sealed 1/0 profile the
    // nonzero-divisor E0801 edge is reachable and the following MIN/-1 E0802
    // edge is present but unsatisfiable under the preceding `right != 0` fact.
    let trap_shape_is_exact = match trap_kind {
        crate::core::mir::MirManagedAnyTrapKind::DivisionByZeroI32 => {
            traps.len() == 2
                && traps.iter().filter(|trap| trap.code == "E0801").count() == 1
                && traps.iter().filter(|trap| trap.code == "E0802").count() == 1
        }
        crate::core::mir::MirManagedAnyTrapKind::SignedOverflowI32 => {
            traps.len() == 1 && traps[0].code == "E0802"
        }
    };
    if !matches!(&returned.value, SymbolicValue::Int(_))
        || !returned.ffi_checks.is_empty()
        || !trap_shape_is_exact
    {
        return Err(format!(
            "ManagedAny trap-cleanup `{}` body did not produce its sealed checked i32 trap set",
            trap_kind.canonical_text()
        ));
    }

    // The core receipt fixes constants that make the checked operation false
    // on every path (1 / 0 or i32::MAX + 1) and seals the prior Any Drop. The
    // symbolic execution above adds the corresponding trap condition; the
    // structural Return exists for MIR ABI consistency only. Never copy the
    // impossible ReturnPath or result value back into the caller.
    state.values.remove(argument);
    state.known_ints.remove(argument);
    state.known_strings.remove(argument);
    state.list_shapes.remove(argument);
    state.traps.extend(traps);
    state.normal_path_terminated = true;
    Ok(())
}

/// Execute the sole admitted generic ManagedAny identity instance. The
/// Checker seal fixes a `Clone; Drop(parameter); Return(clone)` body, so the
/// call consumes the source owner and returns an independent snapshot with
/// identical symbolic contents. All receipt and ABI checks happen before
/// the source is removed from the caller state.
fn eval_materialized_managed_any_identity_call(
    function: &MirFunction,
    program: &MirProgram,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    state: &mut SymbolicState,
    result: &Option<MirValueId>,
    callee: &crate::core::ir::ResolvedCallee,
    type_arguments: &[crate::core::ir::ResolvedTypeId],
    arguments: &[MirValueId],
    effect_receipts: &[crate::core::mir::types::MirCallEffectContract],
    variant_call_contract: Option<&crate::core::mir::types::MirVariantCallAbiContract>,
    instance: &crate::core::mir::MirInstance,
) -> Result<(), String> {
    let crate::core::ir::ResolvedCallee::Function(target_owner) = callee else {
        return Err("ManagedAny identity call must target a canonical function instance".into());
    };
    if instance.function != *target_owner
        || !matches!(
            instance.contract,
            crate::core::mir::MirGenericInstanceContract::ManagedAnyIdentity
        )
    {
        return Err("ManagedAny identity call and instance receipt disagree".into());
    }
    validate_managed_any_identity_call_boundary(
        function,
        program,
        result.as_ref(),
        callee,
        type_arguments,
        arguments,
        effect_receipts,
        variant_call_contract,
    )?;
    let canonical_any = catalog.validate_managed_any_identity_source_argument(type_arguments)?;
    let [argument] = arguments else {
        return Err("ManagedAny identity call must pass exactly one source owner".into());
    };
    let result = result
        .as_ref()
        .ok_or_else(|| "ManagedAny identity call has no result owner".to_string())?;
    if result == argument {
        return Err("ManagedAny identity call aliases its source and result identities".into());
    }
    catalog.validate_glue(&canonical_any, MirGlueOperation::MoveOut)?;
    catalog.validate_glue(&canonical_any, MirGlueOperation::Clone)?;
    let value = state
        .values
        .get(argument)
        .cloned()
        .ok_or_else(|| format!("ManagedAny identity source '{}' is unavailable", argument))?;
    if !symbolic_matches_type(catalog, &canonical_any, &value) {
        return Err("ManagedAny identity source has the wrong symbolic owner shape".into());
    }
    ensure_result_shape(function, catalog, result, &value)?;
    state.values.remove(argument);
    state.known_ints.remove(argument);
    state.known_strings.remove(argument);
    state.list_shapes.remove(argument);
    state.values.insert(result.clone(), value);
    Ok(())
}

/// Symbolically consume the concrete generic identity call admitted by this
/// slice: Copy scalars plus flat Copy Option/Result values.
///
/// The verifier does not infer a callee body from a template name. It first
/// requires the call to name an instance in the canonical instance table,
/// then checks that the executable target still has the exact specialized
/// one-block or total branch identity shape produced by MIR lowering. This
/// keeps the proof tied to the same TypeDesc, instance identity, and ownership
/// contract consumed by the reference, bytecode, and native backends.
fn eval_materialized_identity_call(
    function: &MirFunction,
    program: &MirProgram,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    state: &mut SymbolicState,
    result: &Option<MirValueId>,
    callee: &crate::core::ir::ResolvedCallee,
    type_arguments: &[crate::core::ir::ResolvedTypeId],
    arguments: &[MirValueId],
    variant_call_contract: Option<&crate::core::mir::types::MirVariantCallAbiContract>,
) -> Result<(), String> {
    let crate::core::ir::ResolvedCallee::Function(target_owner) = callee else {
        return Err("MIR verifier generic call callee is not a canonical function instance".into());
    };
    if type_arguments.len() != 1 || arguments.len() != 1 {
        return Err("MIR verifier only admits one-argument concrete generic identity calls".into());
    }
    let instance = program
        .instances()
        .values()
        .find(|instance| instance.function == *target_owner)
        .ok_or_else(|| {
            format!(
                "MIR verifier generic call target '{}' is absent from the instance table",
                target_owner.0
            )
        })?;
    if instance.arguments != type_arguments {
        return Err(format!(
            "MIR verifier generic call target '{}' disagrees with its instance arguments",
            target_owner.0
        ));
    }
    catalog.validate_generic_identity_arguments(type_arguments)?;

    let target = program
        .functions()
        .get(target_owner)
        .ok_or_else(|| format!("MIR verifier generic target '{}' is absent", target_owner.0))?;
    let flat_variant_result = catalog.validate_flat_copy_variant(&target.result).is_ok();
    if flat_variant_result {
        let receipt = variant_call_contract.ok_or_else(|| {
            "MIR verifier generic flat Copy variant call has no canonical ABI receipt".to_string()
        })?;
        let parameter_types = target
            .parameters
            .iter()
            .map(|parameter| {
                target
                    .values
                    .get(parameter)
                    .map(|value| value.ty.clone())
                    .ok_or_else(|| {
                        "MIR verifier generic target parameter TypeDesc is absent".to_string()
                    })
            })
            .collect::<Result<Vec<_>, _>>()?;
        catalog.validate_variant_call_abi_receipt(
            target_owner,
            type_arguments,
            &parameter_types,
            &target.result,
            receipt,
        )?;
    } else if variant_call_contract.is_some() {
        return Err(
            "MIR verifier generic variant call receipt is attached to a non-variant result".into(),
        );
    }
    let [target_parameter] = target.parameters.as_slice() else {
        return Err("MIR verifier generic identity target must have one parameter".into());
    };
    let concrete = type_arguments
        .first()
        .expect("validated one generic type argument");
    let is_owned_string_identity = catalog.validate_owned_string(concrete).is_ok();
    if is_owned_string_identity {
        crate::core::mir::validate_owned_string_identity_shape(target, concrete)?;
    } else {
        crate::core::mir::validate_generic_identity_shape(target, concrete)?;
    }
    let target_parameter_ty = target
        .values
        .get(target_parameter)
        .ok_or_else(|| {
            format!(
                "MIR verifier generic target parameter '{}' is absent",
                target_parameter
            )
        })?
        .ty
        .clone();
    if target_parameter_ty != *concrete || target.result != *concrete {
        return Err(
            "MIR verifier generic identity target is not specialized to its instance argument"
                .into(),
        );
    }
    let argument = arguments
        .first()
        .expect("validated one generic call argument");
    let argument_info = function
        .values
        .get(argument)
        .ok_or_else(|| format!("MIR generic call argument '{}' is absent", argument))?;
    if argument_info.ty != target_parameter_ty {
        return Err("MIR verifier generic call argument disagrees with target TypeDesc".into());
    }
    let symbolic = state
        .values
        .get(argument)
        .cloned()
        .ok_or_else(|| format!("MIR generic call argument '{}' is not defined", argument))?;
    if catalog.validate_owned_string(concrete).is_err() {
        ensure_copy_value(function, catalog, argument)?;
    } else {
        catalog.validate_glue(concrete, MirGlueOperation::Clone)?;
    }
    if !symbolic_matches_type(catalog, concrete, &symbolic) {
        return Err("MIR verifier generic call argument has the wrong concrete Copy shape".into());
    }
    let result = result.as_ref().ok_or_else(|| {
        "MIR verifier generic identity call must produce its canonical result".to_string()
    })?;
    if function
        .values
        .get(result)
        .map_or(true, |value| value.ty != target.result)
    {
        return Err("MIR verifier generic call result disagrees with target TypeDesc".into());
    }
    let caller_constraints = state.constraints.clone();
    if target.blocks.len() == 1 {
        ensure_result_shape(function, catalog, result, &symbolic)?;
        state.values.insert(result.clone(), symbolic);
        return Ok(());
    }
    if !flat_variant_result {
        return Err(
            "MIR verifier generic identity multi-path merge only admits flat Copy Option/Result"
                .into(),
        );
    }
    crate::core::mir::validate_variant_call_return_coverage(target)?;
    let mut target_state = SymbolicState {
        float_domain: state.float_domain,
        callable_entry_values: None,
        callable_entry_constraints: None,
        values: BTreeMap::from([(target_parameter.clone(), symbolic)]),
        constraints: caller_constraints.clone(),
        traps: Vec::new(),
        list_shapes: BTreeMap::new(),
        known_ints: BTreeMap::new(),
        known_strings: BTreeMap::new(),
        ffi_checks: Vec::new(),
        normal_path_terminated: false,
    };
    let mut returns = Vec::new();
    let mut traps = Vec::new();
    explore_block(
        target,
        program,
        catalog,
        &mut target_state,
        &target.entry,
        &mut BTreeSet::new(),
        &mut returns,
        &mut traps,
    )?;
    if !traps.is_empty() {
        return Err("MIR verifier generic identity call has a trapping execution path".into());
    }
    let merged = merge_direct_variant_return_paths(catalog, &target.result, &returns)?;
    state.constraints = caller_constraints;
    ensure_result_shape(function, catalog, result, &merged)?;
    state.values.insert(result.clone(), merged);
    Ok(())
}

/// Symbolically consume the checker-sealed two-argument generic projection
/// admitted by this slice. The MIR receipt fixes the selected formal index and
/// arity; the specialized target body is independently checked to return that
/// exact formal. Only Copy scalar substitutions are admitted here.
fn eval_materialized_argument_projection_call(
    function: &MirFunction,
    program: &MirProgram,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    state: &mut SymbolicState,
    result: &Option<MirValueId>,
    callee: &crate::core::ir::ResolvedCallee,
    type_arguments: &[crate::core::ir::ResolvedTypeId],
    arguments: &[MirValueId],
    variant_call_contract: Option<&crate::core::mir::types::MirVariantCallAbiContract>,
    parameter_index: u32,
    parameter_count: u32,
) -> Result<(), String> {
    let crate::core::ir::ResolvedCallee::Function(target_owner) = callee else {
        return Err(
            "MIR verifier argument projection callee is not a canonical function instance".into(),
        );
    };
    if variant_call_contract.is_some() {
        return Err("MIR verifier argument projection cannot carry a variant ABI receipt".into());
    }
    crate::core::mir::validate_generic_argument_projection_arity(parameter_count)?;
    if parameter_index >= parameter_count || arguments.len() != parameter_count as usize {
        return Err(
            "MIR verifier argument projection receipt has an invalid parameter index or arity"
                .into(),
        );
    }
    let [concrete] = type_arguments else {
        return Err(
            "MIR verifier argument projection requires one exact generic substitution".into(),
        );
    };
    catalog.validate_scalar_generic_arguments(type_arguments)?;
    let instance = program
        .instances()
        .values()
        .find(|instance| instance.function == *target_owner)
        .ok_or_else(|| {
            format!(
                "MIR verifier argument projection target '{}' is absent from the instance table",
                target_owner.0
            )
        })?;
    if instance.arguments != type_arguments
        || instance.contract
            != (crate::core::mir::MirGenericInstanceContract::ScalarArgumentProjection {
                parameter_index,
                parameter_count,
            })
    {
        return Err(
            "MIR verifier argument projection call disagrees with its exact instance receipt"
                .into(),
        );
    }
    let target = program
        .functions()
        .get(target_owner)
        .ok_or_else(|| format!("MIR verifier generic target '{}' is absent", target_owner.0))?;
    crate::core::mir::validate_generic_argument_projection_shape(
        target,
        concrete,
        parameter_index,
        parameter_count,
    )?;
    if target.parameters.len() != parameter_count as usize
        || target.parameters.iter().any(|parameter| {
            target
                .values
                .get(parameter)
                .is_none_or(|value| value.ty != *concrete)
        })
        || target.result != *concrete
    {
        return Err(
            "MIR verifier argument projection target is not specialized to its exact substitution"
                .into(),
        );
    }
    let mut actual_values = Vec::with_capacity(arguments.len());
    for argument in arguments {
        let info = function
            .values
            .get(argument)
            .ok_or_else(|| format!("MIR argument projection argument '{}' is absent", argument))?;
        if info.ty != *concrete {
            return Err(
                "MIR verifier argument projection argument disagrees with the substituted parameter TypeDesc"
                    .into(),
            );
        }
        ensure_copy_value(function, catalog, argument)?;
        let value = state.values.get(argument).cloned().ok_or_else(|| {
            format!(
                "MIR argument projection argument '{}' is not defined",
                argument
            )
        })?;
        if !symbolic_matches_type(catalog, concrete, &value) {
            return Err(
                "MIR verifier argument projection argument has the wrong concrete Copy shape"
                    .into(),
            );
        }
        actual_values.push(value);
    }
    let result = result.as_ref().ok_or_else(|| {
        "MIR verifier argument projection call must produce its canonical result".to_string()
    })?;
    if function
        .values
        .get(result)
        .is_none_or(|value| value.ty != *concrete)
    {
        return Err(
            "MIR verifier argument projection result disagrees with the exact substitution".into(),
        );
    }
    let selected = actual_values
        .into_iter()
        .nth(parameter_index as usize)
        .ok_or_else(|| "MIR verifier selected projection argument is absent".to_string())?;
    ensure_result_shape(function, catalog, result, &selected)?;
    state.values.insert(result.clone(), selected);
    Ok(())
}

fn ensure_result_shape(
    function: &MirFunction,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    result: &MirValueId,
    value: &SymbolicValue,
) -> Result<(), String> {
    let ty = function
        .values
        .get(result)
        .ok_or_else(|| format!("MIR result '{}' is absent", result))?
        .ty
        .clone();
    if symbolic_matches_type(catalog, &ty, value) {
        Ok(())
    } else {
        Err(format!(
            "MIR result '{}' disagrees with canonical TypeDesc shape",
            result
        ))
    }
}

fn symbolic_matches_type(
    catalog: &crate::core::mir::types::MirTypeCatalog,
    ty: &crate::core::ir::ResolvedTypeId,
    value: &SymbolicValue,
) -> bool {
    let Some(descriptor) = catalog.get(ty) else {
        return false;
    };
    if matches!(descriptor.layout, MirLayout::Scalar) && !descriptor.is_canonical_copy_scalar(true)
    {
        return false;
    }
    if let SymbolicValue::OrdinaryMapOwnedAnyV2ValuesUnpackedOwner {
        owner_id,
        payload_type,
        payload,
    } = value
    {
        return !owner_id.is_empty()
            && payload_type == ty
            && symbolic_matches_type(catalog, payload_type, payload);
    }
    match (&descriptor.layout, &descriptor.abi, value) {
        (_, _, SymbolicValue::Unit) if descriptor.is_canonical_ffi_unit() => true,
        (
            MirLayout::Scalar,
            MirAbiClass::Integer {
                bits: 32 | 64,
                signed: true,
            },
            SymbolicValue::Int(_),
        )
        | (MirLayout::Scalar, MirAbiClass::Bool, SymbolicValue::Bool(_)) => true,
        (
            MirLayout::Scalar,
            MirAbiClass::Float { bits: 32 | 64 },
            SymbolicValue::Opaque { ty: actual_ty },
        ) => actual_ty == ty,
        (MirLayout::Scalar, MirAbiClass::Float { bits: 64 }, SymbolicValue::Float(_)) => true,
        (MirLayout::Handle, MirAbiClass::StringHandle, SymbolicValue::Opaque { ty: actual_ty }) => {
            actual_ty == ty && catalog.validate_owned_string(ty).is_ok()
        }
        (MirLayout::Handle, MirAbiClass::StringHandle, SymbolicValue::String(_)) => {
            catalog.validate_owned_string(ty).is_ok()
        }
        (MirLayout::Handle, MirAbiClass::OpaqueHandle, SymbolicValue::Opaque { ty: actual_ty }) => {
            actual_ty == ty && catalog.validate_session_channel(ty).is_ok()
        }
        (MirLayout::MapRoot, MirAbiClass::OpaqueHandle, SymbolicValue::MapRoot { .. }) => {
            catalog.validate_glue(ty, MirGlueOperation::MoveOut).is_ok()
        }
        (
            MirLayout::OrdinaryMapOwnerLifecycleI32StringV1,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnerLifecycleV1 { .. },
        ) => catalog.validate_glue(ty, MirGlueOperation::MoveOut).is_ok(),
        (
            MirLayout::OrdinaryMapOwnedGetI32StringV1,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedGetI32StringV1 { .. },
        ) => catalog.validate_glue(ty, MirGlueOperation::MoveOut).is_ok(),
        (
            MirLayout::OrdinaryMapOwnedAnyV2,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedAnyV2 { .. },
        ) => catalog.validate_glue(ty, MirGlueOperation::MoveOut).is_ok(),
        (
            MirLayout::OrdinaryMapOwnedAnyV2Payload,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedAnyV2Payload {
                payload_type,
                payload,
            },
        ) => {
            ty == &crate::core::mir::types::ordinary_map_owned_any_v2_payload_type_id()
                && catalog.get(payload_type).is_some()
                && symbolic_matches_type(catalog, payload_type, payload)
                && [
                    MirGlueOperation::MoveOut,
                    MirGlueOperation::Clone,
                    MirGlueOperation::Drop,
                ]
                .into_iter()
                .all(|operation| catalog.validate_glue(ty, operation).is_ok())
        }
        (
            MirLayout::List { element },
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedAnyV2Values { owner_id, entries },
        ) => {
            let mut owner_ids = BTreeSet::new();
            !owner_id.is_empty()
                && symbolic_ordinary_map_owned_any_v2_values_owner_ids(value, &mut owner_ids)
                    .is_ok()
                && ty == &crate::core::mir::types::ordinary_map_owned_any_v2_values_type_id()
                && element
                    == &crate::core::mir::types::ordinary_map_owned_any_v2_values_element_type_id()
                && [
                    MirGlueOperation::MoveOut,
                    MirGlueOperation::Clone,
                    MirGlueOperation::Drop,
                ]
                .into_iter()
                .all(|operation| catalog.validate_list_glue(ty, operation).is_ok())
                && entries
                    .iter()
                    .all(|entry| symbolic_matches_type(catalog, element, entry))
        }
        (
            MirLayout::List { element },
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedAnyV2Keys { entries },
        ) => {
            catalog.validate_owned_string_list(ty).is_ok()
                && element
                    == &crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String)
                && [
                    MirGlueOperation::MoveOut,
                    MirGlueOperation::Clone,
                    MirGlueOperation::Drop,
                ]
                .into_iter()
                .all(|operation| catalog.validate_list_glue(ty, operation).is_ok())
                && entries
                    .iter()
                    .all(|entry| symbolic_matches_type(catalog, element, entry))
        }
        (
            MirLayout::OrdinaryMapOwnedAnyV2ValuesElement,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::OrdinaryMapOwnedAnyV2ValuesElement {
                owner_id,
                payload_type,
                payload,
            },
        ) => {
            let mut owner_ids = BTreeSet::new();
            !owner_id.is_empty()
                && symbolic_ordinary_map_owned_any_v2_values_owner_ids(value, &mut owner_ids)
                    .is_ok()
                && ty
                    == &crate::core::mir::types::ordinary_map_owned_any_v2_values_element_type_id()
                && catalog.get(payload_type).is_some()
                && symbolic_matches_type(catalog, payload_type, payload)
                && [
                    MirGlueOperation::MoveOut,
                    MirGlueOperation::Clone,
                    MirGlueOperation::Drop,
                ]
                .into_iter()
                .all(|operation| catalog.validate_glue(ty, operation).is_ok())
        }
        (
            MirLayout::ManagedAnyI32StringV1,
            MirAbiClass::OpaqueHandle,
            SymbolicValue::ManagedAnyI32StringV1 { .. },
        ) => {
            catalog.is_managed_any_i32_string_v1(ty)
                && [
                    MirGlueOperation::MoveOut,
                    MirGlueOperation::Clone,
                    MirGlueOperation::Drop,
                ]
                .into_iter()
                .all(|operation| catalog.validate_glue(ty, operation).is_ok())
        }
        (MirLayout::Tuple(elements), _, SymbolicValue::Tuple(values)) => {
            elements.len() == values.len()
                && elements
                    .iter()
                    .zip(values)
                    .all(|(ty, value)| symbolic_matches_type(catalog, ty, value))
        }
        (
            MirLayout::Record { nominal, fields },
            _,
            SymbolicValue::Record {
                nominal: actual_nominal,
                fields: actual_fields,
            },
        ) => {
            nominal == actual_nominal
                && fields.len() == actual_fields.len()
                && fields.iter().all(|field| {
                    actual_fields
                        .get(&field.id)
                        .is_some_and(|value| symbolic_matches_type(catalog, &field.ty, value))
                })
        }
        (MirLayout::Set { .. }, MirAbiClass::SetHandle, SymbolicValue::Set { .. }) => catalog
            .validate_set_glue(ty, MirGlueOperation::MoveOut)
            .is_ok(),
        (MirLayout::List { .. }, MirAbiClass::OpaqueHandle, SymbolicValue::List { .. }) => catalog
            .validate_list_glue(ty, MirGlueOperation::MoveOut)
            .is_ok(),
        (
            MirLayout::Option { variants, .. }
            | MirLayout::Result { variants, .. }
            | MirLayout::Enum { variants, .. },
            MirAbiClass::Aggregate,
            SymbolicValue::Variant {
                nominal: actual_nominal,
                tag: _,
                payload,
                active_variant,
            },
        ) => {
            let expected_nominal = match &descriptor.layout {
                MirLayout::Option { .. } => "builtin:type:Option".to_string(),
                MirLayout::Result { .. } => "builtin:type:Result".to_string(),
                MirLayout::Enum { nominal, .. } => {
                    // Only the promoted multi-target union contract admits a
                    // symbolic Enum variant; checker-materialized user enums
                    // have no verifier capability to match against.
                    if descriptor.kind != MirTypeKind::FlowStateSet
                        || catalog.validate_multi_target_union_variant(ty).is_err()
                    {
                        return false;
                    }
                    nominal.as_str().to_string()
                }
                _ => return false,
            };
            let fields_match = if let Some(active_variant) = active_variant {
                variants
                    .iter()
                    .find(|variant| variant.id == *active_variant)
                    .is_some_and(|variant| {
                        payload.len() == variant.fields.len()
                            && variant.fields.iter().all(|field| {
                                payload.get(&field.id).is_some_and(|value| {
                                    symbolic_matches_type(catalog, &field.ty, value)
                                })
                            })
                    })
            } else {
                let expected_fields = variants
                    .iter()
                    .flat_map(|variant| variant.fields.iter())
                    .collect::<Vec<_>>();
                payload.len() == expected_fields.len()
                    && expected_fields.iter().all(|field| {
                        payload
                            .get(&field.id)
                            .is_some_and(|value| symbolic_matches_type(catalog, &field.ty, value))
                    })
            };
            actual_nominal.as_str() == expected_nominal && fields_match
        }
        _ => false,
    }
}

fn symbolic_construct(
    function: &MirFunction,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    result: &MirValueId,
    kind: &MirAggregateKind,
    values: Vec<SymbolicValue>,
) -> Result<SymbolicValue, String> {
    let result_ty = function
        .values
        .get(result)
        .ok_or_else(|| format!("MIR aggregate result '{}' is absent", result))?
        .ty
        .clone();
    let descriptor = catalog
        .get(&result_ty)
        .ok_or_else(|| format!("MIR aggregate result '{}' TypeDesc is absent", result))?;
    match (kind, &descriptor.layout) {
        (MirAggregateKind::Tuple, MirLayout::Tuple(elements)) if elements.len() == values.len() => {
            Ok(SymbolicValue::Tuple(values))
        }
        (
            MirAggregateKind::Record {
                nominal,
                fields: field_ids,
            },
            MirLayout::Record {
                nominal: expected_nominal,
                fields: layout_fields,
            },
        ) if nominal == expected_nominal
            && field_ids.len() == values.len()
            && field_ids.len() == layout_fields.len() =>
        {
            let mut fields = BTreeMap::new();
            for (field, value) in field_ids.iter().cloned().zip(values) {
                if fields.insert(field, value).is_some() {
                    return Err("MIR record construction repeats a field".into());
                }
            }
            Ok(SymbolicValue::Record {
                nominal: expected_nominal.clone(),
                fields,
            })
        }
        _ => Err("MIR aggregate construction disagrees with canonical TypeDesc".into()),
    }
}

fn symbolic_update_record(
    function: &MirFunction,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    result: &MirValueId,
    base: SymbolicValue,
    nominal: &crate::core::ir::NominalTypeId,
    fields: &[crate::core::NodeId],
    update_values: Vec<SymbolicValue>,
    require_copy: bool,
) -> Result<SymbolicValue, String> {
    let result_ty = function
        .values
        .get(result)
        .ok_or_else(|| format!("MIR record update result '{}' is absent", result))?
        .ty
        .clone();
    if require_copy {
        ensure_copy_value(function, catalog, result)?;
    } else {
        catalog.validate_glue(&result_ty, MirGlueOperation::MoveOut)?;
        catalog.validate_glue(&result_ty, MirGlueOperation::Drop)?;
    }

    let descriptor = catalog
        .get(&result_ty)
        .ok_or_else(|| format!("MIR record update result '{}' TypeDesc is absent", result))?;
    let MirLayout::Record {
        nominal: expected_nominal,
        fields: layout_fields,
    } = &descriptor.layout
    else {
        return Err("MIR record update result has no canonical record layout".into());
    };
    let SymbolicValue::Record {
        nominal: base_nominal,
        fields: mut base_fields,
    } = base
    else {
        return Err("MIR record update base is not a symbolic record".into());
    };
    if nominal != expected_nominal || &base_nominal != expected_nominal {
        return Err("MIR record update nominal disagrees with TypeDesc".into());
    }
    if fields.len() != update_values.len() {
        return Err("MIR record update field/value arity disagrees".into());
    }
    if base_fields.len() != layout_fields.len()
        || layout_fields
            .iter()
            .any(|field| !base_fields.contains_key(&field.id))
    {
        return Err("MIR record update base disagrees with TypeDesc fields".into());
    }

    let mut seen = BTreeSet::new();
    for (field, value) in fields.iter().zip(update_values) {
        if !seen.insert(field) {
            return Err(format!("MIR record update repeats field '{}'", field.0));
        }
        let expected = layout_fields
            .iter()
            .find(|candidate| candidate.id == *field)
            .ok_or_else(|| format!("MIR record update field '{}' is absent", field.0))?;
        if !symbolic_matches_type(catalog, &expected.ty, &value) {
            return Err(format!(
                "MIR record update field '{}' disagrees with TypeDesc",
                field.0
            ));
        }
        base_fields.insert(field.clone(), value);
    }
    Ok(SymbolicValue::Record {
        nominal: expected_nominal.clone(),
        fields: base_fields,
    })
}

fn eval_binary(
    function: &MirFunction,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    state: &mut SymbolicState,
    op: crate::core::ir::ResolvedBinaryOp,
    left_id: &MirValueId,
    right_id: &MirValueId,
    left: SymbolicValue,
    right: SymbolicValue,
    result: &MirValueId,
) -> Result<SymbolicValue, String> {
    use crate::core::ir::ResolvedBinaryOp as Op;
    match (left, right) {
        (SymbolicValue::Int(left), SymbolicValue::Int(right)) => {
            let output = match op {
                Op::Add => Int::add(&[&left, &right]),
                Op::Subtract => Int::sub(&[&left, &right]),
                Op::Multiply => Int::mul(&[&left, &right]),
                Op::Power => {
                    let width = checked_power_width_for_values(
                        function, catalog, left_id, right_id, result,
                    )?;
                    let encoding = encode_checked_integer_power(
                        &left,
                        &right,
                        width,
                        POWER_PROFILE_0_1_11_COMPAT,
                    );
                    // Typed input values are range-pinned at introduction,
                    // MIR constants are validated against their TypeDesc,
                    // and all earlier producers preserve their checked width.
                    // This static typing fact is deliberately not surfaced as
                    // a Power runtime trap.
                    state
                        .constraints
                        .push(encoding.faults.operands_outside_source_width.not());
                    add_definedness(state, encoding.faults.negative_exponent.not(), "E0800")?;
                    add_definedness(state, encoding.faults.exponent_above_u32.not(), "E0800")?;
                    add_definedness(
                        state,
                        encoding.faults.checked_multiply_overflow.not(),
                        "E0802",
                    )?;
                    encoding.value
                }
                Op::Divide | Op::Remainder => {
                    let kind = value_scalar_kind(function, catalog, result)?;
                    let ScalarKind::Int { bits } = kind else {
                        return Err("MIR integer operation has non-integer result TypeDesc".into());
                    };
                    let (output, _defined) =
                        checked_int_division(&left, &right, bits, op == Op::Remainder);
                    let zero = Int::from_i64(0);
                    let signed_min = Int::from_i64(if bits == 32 {
                        i32::MIN as i64
                    } else {
                        i64::MIN
                    });
                    let nonzero_divisor = right.ne(&zero);
                    let no_signed_overflow =
                        Bool::and(&[&left.eq(&signed_min), &right.eq(Int::from_i64(-1))]).not();
                    add_definedness(state, nonzero_divisor, "E0801")?;
                    add_definedness(state, no_signed_overflow, "E0802")?;
                    output
                }
                Op::Equal => return Ok(SymbolicValue::Bool(left.eq(&right))),
                Op::NotEqual => return Ok(SymbolicValue::Bool(left.eq(&right).not())),
                Op::Less => return Ok(SymbolicValue::Bool(left.lt(&right))),
                Op::Greater => return Ok(SymbolicValue::Bool(left.gt(&right))),
                Op::LessEqual => return Ok(SymbolicValue::Bool(left.le(&right))),
                Op::GreaterEqual => return Ok(SymbolicValue::Bool(left.ge(&right))),
                _ => return Err("MIR integer binary operation is outside verifier contract".into()),
            };
            if matches!(op, Op::Add | Op::Subtract | Op::Multiply) {
                let ScalarKind::Int { bits } = value_scalar_kind(function, catalog, result)? else {
                    return Err("MIR arithmetic result is not an integer TypeDesc".into());
                };
                add_definedness(state, int_range_constraint(&output, bits), "E0802")?;
            }
            Ok(SymbolicValue::Int(output))
        }
        (SymbolicValue::Float(left), SymbolicValue::Float(right)) => {
            // IEEE comparison predicates carry no definedness obligation:
            // NaN is unordered, equality is false on NaN and true for the
            // two zero signs, and != is the exact negation of IEEE equality.
            // This is valid both for ordinary finite-entry proofs and the
            // separate full-IEEE FFI profile.
            match op {
                Op::Equal => return Ok(SymbolicValue::Bool(left.eq_fpa(&right))),
                Op::NotEqual => return Ok(SymbolicValue::Bool(left.eq_fpa(&right).not())),
                Op::Less => return Ok(SymbolicValue::Bool(left.lt(&right))),
                Op::Greater => return Ok(SymbolicValue::Bool(left.gt(&right))),
                Op::LessEqual => return Ok(SymbolicValue::Bool(left.le(&right))),
                Op::GreaterEqual => return Ok(SymbolicValue::Bool(left.ge(&right))),
                _ => {}
            }
            // LLVM `fadd`/`fsub`/`fmul`/`fdiv` and Rust `+`/`-`/`*`/`/` on
            // f64 all round nearest-ties-even, so this is the exact runtime
            // semantics.  R6-1067: Multiply/Divide join.  The runtime owns
            // two distinct traps on this face and the verifier restates
            // both where the runtime raises them: the ±0.0 divisor is the
            // E0801 division-definedness violation (same face as the
            // integer zero divisor), and overflow stays IEEE-defined (±inf)
            // owned by the E0813 finiteness obligation.
            if op == Op::Divide {
                let zero = Float::from_f64(0.0);
                let divisor_defined = right.eq_fpa(&zero).not();
                add_definedness(state, divisor_defined, "E0801")?;
            }
            let rounding = RoundingMode::round_nearest_ties_to_even();
            let output = match op {
                Op::Add => left.add_with_rounding_mode(&right, &rounding),
                Op::Subtract => left.sub_with_rounding_mode(&right, &rounding),
                Op::Multiply => left.mul_with_rounding_mode(&right, &rounding),
                Op::Divide => left.div_with_rounding_mode(&right, &rounding),
                _ => {
                    return Err(format!(
                        "{}: MIR verifier f64 operation {op:?} is outside the encoded IEEE arithmetic contract; {} remains NotInTrustedSubset",
                        crate::core::mir::types::MIR_VERIFIER_FLOAT_BOUNDARY_CODE,
                        crate::core::mir::types::MIR_FLOAT_NOT_FINITE_TRAP_CODE
                    ));
                }
            };
            // The reference executor and native emitter both trap unless the
            // operands and the result are finite; restate the full trap
            // predicate here so E0813 stays owned by the operation that the
            // runtime traps at, not by the introduction argument.
            let finite = Bool::and(&[
                &float_is_finite(&left),
                &Bool::and(&[&float_is_finite(&right), &float_is_finite(&output)]),
            ]);
            add_definedness(
                state,
                finite,
                crate::core::mir::types::MIR_FLOAT_NOT_FINITE_TRAP_CODE,
            )?;
            Ok(SymbolicValue::Float(output))
        }
        (SymbolicValue::Bool(left), SymbolicValue::Bool(right)) => match op {
            Op::Equal => Ok(SymbolicValue::Bool(left.eq(&right))),
            Op::NotEqual => Ok(SymbolicValue::Bool(left.eq(&right).not())),
            Op::LogicalAnd => Ok(SymbolicValue::Bool(Bool::and(&[&left, &right]))),
            Op::LogicalOr => Ok(SymbolicValue::Bool(Bool::or(&[&left, &right]))),
            _ => Err("MIR boolean binary operation is outside verifier contract".into()),
        },
        _ => Err("MIR binary operands have incompatible scalar kinds".into()),
    }
}

/// Resolve executable Power from all three exact MIR TypeDesc identities.
/// A Z3 Int sort alone carries no source width and cannot choose the profile.
fn checked_power_width_for_values(
    function: &MirFunction,
    catalog: &crate::core::mir::types::MirTypeCatalog,
    left: &MirValueId,
    right: &MirValueId,
    result: &MirValueId,
) -> Result<CheckedPowerWidth, String> {
    let left_ty = &function
        .values
        .get(left)
        .ok_or_else(|| format!("MIR Power left value '{}' is absent", left))?
        .ty;
    let right_ty = &function
        .values
        .get(right)
        .ok_or_else(|| format!("MIR Power exponent value '{}' is absent", right))?
        .ty;
    let result_ty = &function
        .values
        .get(result)
        .ok_or_else(|| format!("MIR Power result value '{}' is absent", result))?
        .ty;
    if left_ty != right_ty || right_ty != result_ty {
        return Err(
            "MIR checked Power requires identical base, exponent, and result TypeDesc identities"
                .into(),
        );
    }
    match value_scalar_kind(function, catalog, result)? {
        ScalarKind::Int { bits: 32 } => Ok(CheckedPowerWidth::I32),
        ScalarKind::Int { bits: 64 } => Ok(CheckedPowerWidth::I64),
        _ => Err("MIR checked Power requires a signed i32 or i64 TypeDesc".into()),
    }
}

/// The IEEE finite-only predicate: neither NaN nor an infinity.  This is the
/// exact negation of the runtime E0813 trap condition (SD-9).
fn float_is_finite(value: &Float) -> Bool {
    Bool::and(&[&value.is_nan().not(), &value.is_infinite().not()])
}

fn add_definedness(state: &mut SymbolicState, defined: Bool, code: &str) -> Result<(), String> {
    let mut trap_condition = state.constraints.clone();
    trap_condition.push(defined.not());
    state.traps.push(SymbolicTrap {
        condition: trap_condition,
        code: code.into(),
        subject: None,
    });
    state.constraints.push(defined);
    Ok(())
}

fn add_ordinary_map_owned_any_v2_root_publish_capacity_failure(
    state: &mut SymbolicState,
    instruction_id: &crate::core::mir::MirInstructionId,
) -> Result<(), String> {
    // A fresh symbol is required even when a loop revisits the same stable
    // MIR instruction: capacity outcomes belong to dynamic executions, not
    // just source locations.
    let published = Bool::fresh_const(&format!(
        "mir.ordinary_map_owned_any_v2.root_publish.{}",
        instruction_id.as_str()
    ));
    add_definedness(state, published, "E0800")
}

fn add_ordinary_map_owner_lifecycle_v1_capacity_failure(
    state: &mut SymbolicState,
    instruction_id: &crate::core::mir::MirInstructionId,
    operation: &str,
) -> Result<(), String> {
    // Native lifecycle-v1 helpers return a zero/null/invalid result when a
    // fallible allocation or handle publication fails. Those failures abort
    // with E0800; make success a fresh path condition so a proof cannot
    // silently assume allocator capacity. Bytecode/reference consumers may
    // use infallible standard collection operations, but the shared MIR
    // contract follows the stricter native failure surface.
    let published = Bool::fresh_const(&format!(
        "mir.ordinary_map_owner_lifecycle_i32_string_v1.{operation}_capacity.{}",
        instruction_id.as_str()
    ));
    add_definedness(state, published, "E0800")
}

fn add_ordinary_map_owner_lifecycle_v1_size_overflow(
    state: &mut SymbolicState,
    size: &Int,
) -> Result<(), String> {
    let in_i32_range = size.le(Int::from_i64(i32::MAX as i64));
    // The bytecode VM reports the checked conversion as E0802, while the
    // native adapter currently maps the helper's -1 sentinel to E0800.
    // Preserve both backend-visible outcomes for the same overflowing-size
    // path so it cannot be mistaken for a proof.
    let mut native_overflow = state.constraints.clone();
    native_overflow.push(in_i32_range.not());
    state.traps.push(SymbolicTrap {
        condition: native_overflow,
        code: "E0800".into(),
        subject: None,
    });
    add_definedness(state, in_i32_range, "E0802")
}

fn add_ordinary_map_owned_any_v2_values_clone_capacity_failure(
    state: &mut SymbolicState,
    instruction_id: &crate::core::mir::MirInstructionId,
) -> Result<(), String> {
    // Native and VM both clone this exact List by staging a fresh backing
    // allocation and then deep-cloning every descriptor-pinned owner into it.
    // Any backing allocation, payload clone, or append failure is E0800 and
    // leaves the original snapshot live; one fresh success predicate therefore
    // represents the conjunction of all stages without hiding a failure edge.
    let cloned = Bool::fresh_const(&format!(
        "mir.ordinary_map_owned_any_v2.values_clone.{}",
        instruction_id.as_str()
    ));
    add_definedness(state, cloned, "E0800")
}

