    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn ordinary_map_owned_any_v2_values_is_a_sorted_owned_snapshot() {
        let program = canonical(
            r#"
            type Label { text: string }

            func snapshot_survives_source_updates() -> i32 {
                ensures: result == 3
                let number = 7
                let label = Label { text: "mixed payload" }
                let empty = map_new()
                let with_z = map_set(empty, "z", number)
                let with_a = map_set(with_z, "a", label)
                let snapshot = values(with_a)
                let changed = map_remove(with_a, "z")
                let remaining = map_size(changed)
                drop(empty)
                drop(with_z)
                drop(with_a)
                drop(changed)
                let captured = snapshot.len()
                drop(snapshot)
                drop(label)
                captured + remaining
            }

            func empty_values_snapshot() -> i32 {
                ensures: result == 0
                let label = Label { text: "removed" }
                let empty = map_new()
                let one = map_set(empty, "removed", label)
                let cleared = map_remove(one, "removed")
                let snapshot = values(cleared)
                let length = snapshot.len()
                drop(snapshot)
                drop(empty)
                drop(one)
                drop(cleared)
                drop(label)
                length
            }

            func main() -> i32 { 0 }
            "#,
        );
        let receipts = program
            .ordinary_map_owned_any_v2_values_result_receipts()
            .expect("exact Core Values source/result/binding/Drop receipts");
        assert_eq!(receipts.len(), 2);
        crate::verifier::validate_mir_capabilities(&program)
            .expect("Values consumes the exact payload selection and result receipts");
        assert_capacity_counterexample(&program, "snapshot_survives_source_updates");
        assert_capacity_counterexample(&program, "empty_values_snapshot");

        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload selection census")
            .expect("mixed V2 Map has selected payload types");
        let label_type = selection
            .selected_types
            .iter()
            .find(|selected| {
                selected.type_id
                    != crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
            })
            .expect("the record payload remains in the selection closure")
            .type_id
            .clone();
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let (label_value, _) =
            super::symbolic_value_for_type(program.type_catalog(), &label_type, "v2.values.label")
                .expect("symbolic selected record payload");
        let entries = BTreeMap::from([
            (
                "z".to_string(),
                super::SymbolicOrdinaryMapOwnedAnyV2Entry {
                    payload_type: i32_type.clone(),
                    payload: Box::new(SymbolicValue::Int(Int::from_i64(7))),
                },
            ),
            (
                "a".to_string(),
                super::SymbolicOrdinaryMapOwnedAnyV2Entry {
                    payload_type: label_type.clone(),
                    payload: Box::new(label_value),
                },
            ),
        ]);
        let mut snapshot_state = empty_values_test_state();
        let elements = super::symbolic_ordinary_map_owned_any_v2_values_snapshot(
            program.type_catalog(),
            crate::core::mir::types::ordinary_map_owned_any_v2_values_element_type_id(),
            &entries,
            "test.values.sorted-elements",
            &mut snapshot_state,
        )
        .expect("selected payload values become owned list elements in sorted key order");
        assert_eq!(elements.len(), 2);
        assert!(matches!(
            &elements[0],
            SymbolicValue::OrdinaryMapOwnedAnyV2ValuesElement { payload_type, .. }
                if payload_type == &label_type
        ));
        assert!(matches!(
            &elements[1],
            SymbolicValue::OrdinaryMapOwnedAnyV2ValuesElement { payload_type, payload, .. }
                if payload_type == &i32_type && matches!(payload.as_ref(), SymbolicValue::Int(_))
        ));
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn ordinary_map_owned_any_v2_values_unpack_models_capacity_and_keeps_traps() {
        let program = canonical(
            r#"
            type Label { text: string }

            func values_unpack_hit() -> i32 {
                ensures: result == 41
                let label = Label { text: "selected record" }
                let empty = map_new()
                let number = map_set(empty, "answer", 41)
                let root = map_set(number, "label", label)
                let snapshot = values(root)
                let result = snapshot[0] as i32
                drop(snapshot)
                drop(empty)
                drop(number)
                drop(root)
                drop(label)
                result
            }

            func values_unpack_out_of_bounds() -> i32 {
                ensures: result == 41
                let label = Label { text: "selected record" }
                let empty = map_new()
                let number = map_set(empty, "answer", 41)
                let root = map_set(number, "label", label)
                let snapshot = values(root)
                let result = snapshot[2] as i32
                drop(snapshot)
                drop(empty)
                drop(number)
                drop(root)
                drop(label)
                result
            }

            func main() -> i32 { 0 }
            "#,
        );
        crate::verifier::validate_mir_capabilities(&program)
            .expect("each Values cast is bound to the exact selected payload and snapshot Drop");
        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("direct indexed cast result receipts");
        assert_eq!(receipts.len(), 2);

        for (name, expected) in [
            ("values_unpack_hit", VerifStatus::Disproven),
            ("values_unpack_out_of_bounds", VerifStatus::Disproven),
        ] {
            assert_contract(&program, name, expected);
        }

        let wrong_tag_source = r#"
            type Label { text: string }
            func main() -> i32 {
                let label = Label { text: "selected record" }
                let text = "wrong payload tag"
                let empty = map_new()
                let strings = map_set(empty, "a", text)
                let number = map_set(strings, "b", 41)
                let root = map_set(number, "c", label)
                let snapshot = values(root)
                let result = snapshot[0] as i32
                drop(snapshot)
                drop(empty)
                drop(strings)
                drop(number)
                drop(root)
                drop(label)
                drop(text)
                result
            }
        "#;
        let wrong_tag_tokens = Lexer::new(wrong_tag_source)
            .tokenize()
            .expect("lex statically mismatched Values payload");
        let wrong_tag_file = Parser::new(wrong_tag_tokens)
            .parse_file()
            .expect("parse statically mismatched Values payload");
        let wrong_tag_diagnostics = crate::core::check_program(&wrong_tag_file)
            .expect_err("a statically wrong key-sorted payload type must fail in Checker");
        assert!(
            wrong_tag_diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code.as_deref() == Some("E0200")),
            "wrong-index payload cast must fail closed: {wrong_tag_diagnostics:?}"
        );

        let results = verify_program(&program, "v2-values-unpack-capacity-edges".into())
            .expect("ValuesUnpack capacity stages are explicit symbolic traps");
        let hit = results
            .iter()
            .find(|result| result.func_name.ends_with("values_unpack_hit"))
            .expect("ValuesUnpack hit contract result");
        assert!(
            hit.message.contains("can reach trap 'E0800'"),
            "selected-owner and typed-clone Capacity failures must remain visible: {}",
            hit.message
        );

        {
            let name = "values_unpack_out_of_bounds";
            let owner = crate::core::NodeId(format!("function:{name}"));
            let error = MirReferenceInterpreter::new(&program)
                .execute(&owner, &[])
                .expect_err("statically known out-of-range Values index reaches E0803");
            assert!(error.message.contains("E0803"), "{error:?}");
        }
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn ordinary_map_owned_any_v2_values_unpack_has_isolated_stage_traps() {
        let program = canonical(
            r#"
            type Label { text: string }

            func observe() -> i32 {
                let label = Label { text: "selected label" }
                let text = "selected string"
                let empty = map_new()
                let number = map_set(empty, "a-number", 41)
                let strings = map_set(number, "b-string", text)
                let root = map_set(strings, "c-label", label)
                let snapshot = values(root)
                let selected_number = snapshot[0] as i32
                let selected_text = snapshot[1] as string
                let selected_label = snapshot[2] as Label
                drop(selected_number)
                drop(selected_text)
                drop(selected_label)
                drop(snapshot)
                drop(empty)
                drop(number)
                drop(strings)
                drop(root)
                drop(label)
                drop(text)
                0
            }

            func main() -> i32 { 0 }
            "#,
        );
        let function = program
            .functions()
            .get(&crate::core::NodeId("function:observe".into()))
            .expect("V2 ValuesUnpack observer");
        let catalog = program.type_catalog();
        let instructions = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .filter(|instruction| {
                matches!(
                    instruction.kind,
                    MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack { .. }
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(instructions.len(), 3);

        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection receipt")
            .expect("i32, String, and Label selection profile");
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let label_type = selection
            .selected_types
            .iter()
            .find(|selected| selected.type_id != i32_type && selected.type_id != string_type)
            .expect("selected Label TypeDesc")
            .type_id
            .clone();
        let mut entries = BTreeMap::new();
        for (key, ty) in [
            ("a-number", i32_type.clone()),
            ("b-string", string_type.clone()),
            ("c-label", label_type.clone()),
        ] {
            let (payload, _) = super::symbolic_value_for_type(
                catalog,
                &ty,
                &format!("v2.values.unpack.capacity.{key}"),
            )
            .expect("selected profile has a symbolic payload");
            entries.insert(
                key.to_string(),
                super::SymbolicOrdinaryMapOwnedAnyV2Entry {
                    payload_type: ty,
                    payload: Box::new(payload),
                },
            );
        }
        let snapshot_owner = "test.values.unpack-capacity";
        let mut snapshot_state = empty_values_test_state();
        let snapshot = super::symbolic_ordinary_map_owned_any_v2_values_snapshot(
            catalog,
            crate::core::mir::types::ordinary_map_owned_any_v2_values_element_type_id(),
            &entries,
            snapshot_owner,
            &mut snapshot_state,
        )
        .expect("selected payloads form the exact sorted Values snapshot");
        let snapshot_constraints = snapshot_state.constraints;

        let seed = |instruction: &crate::core::mir::MirInstruction, index_value: i64| {
            let MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack {
                values: values_id,
                index,
                ..
            } = &instruction.kind
            else {
                unreachable!()
            };
            SymbolicState {
                float_domain: SymbolicFloatDomain::Finite,
                values: BTreeMap::from([
                    (
                        values_id.clone(),
                        SymbolicValue::OrdinaryMapOwnedAnyV2Values {
                            owner_id: snapshot_owner.to_string(),
                            entries: snapshot.clone(),
                        },
                    ),
                    (
                        index.clone(),
                        SymbolicValue::Int(Int::from_i64(index_value)),
                    ),
                ]),
                constraints: snapshot_constraints.clone(),
                callable_entry_values: None,
                callable_entry_constraints: None,
                traps: Vec::new(),
                list_shapes: BTreeMap::new(),
                known_ints: BTreeMap::new(),
                known_strings: BTreeMap::new(),
                ffi_checks: Vec::new(),
                normal_path_terminated: false,
            }
        };
        let trap_statuses = |state: &SymbolicState| {
            let mut session = super::SolverSession::new(crate::verifier::ctx::DEFAULT_TIMEOUT_MS)
                .expect("trap reachability solver");
            state
                .traps
                .iter()
                .map(|trap| session.check_scope(&super::conjunction(&trap.condition)).0)
                .collect::<Vec<_>>()
        };

        for (target_type, index_value, expected_markers) in [
            (
                i32_type.clone(),
                0,
                vec!["E0803", "selected_owner", "E0800", "unpack_capacity"],
            ),
            (
                string_type.clone(),
                1,
                vec![
                    "E0803",
                    "selected_owner",
                    "E0800",
                    "unpack_capacity",
                    "string_clone",
                    "string_publish",
                ],
            ),
            (
                label_type.clone(),
                2,
                vec![
                    "E0803",
                    "selected_owner",
                    "E0800",
                    "unpack_capacity",
                    "string_clone",
                    "string_publish",
                ],
            ),
        ] {
            let instruction = instructions
                .iter()
                .copied()
                .find(|instruction| {
                    let MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack { result, .. } =
                        &instruction.kind
                    else {
                        unreachable!()
                    };
                    function.values.get(result).map(|value| &value.ty) == Some(&target_type)
                })
                .expect("one exact indexed unpack per selected TypeDesc");
            let mut state = seed(instruction, index_value);
            eval_instruction(
                function,
                &program,
                catalog,
                &mut state,
                &instruction.id,
                &instruction.kind,
            )
            .expect("isolated ValuesUnpack symbolic execution");
            assert_eq!(state.traps.len(), expected_markers.len());
            assert_eq!(state.traps[0].code, "E0803");
            for (index, marker) in expected_markers.iter().enumerate().skip(1) {
                assert_eq!(state.traps[index].code, "E0800");
                if *marker != "E0800" {
                    assert!(
                        state.traps[index]
                            .condition
                            .iter()
                            .any(|condition| condition.to_string().contains(marker)),
                        "trap {index} for {} lacks stage {marker}: {:?}",
                        target_type.as_str(),
                        state.traps[index].condition
                    );
                }
            }
            let mut expected = vec![SatResult::Sat; expected_markers.len()];
            expected[0] = SatResult::Unsat;
            expected[2] = SatResult::Unsat;
            assert_eq!(
                trap_statuses(&state),
                expected,
                "only bounds is impossible for a correctly selected {} payload",
                target_type.as_str()
            );
        }

        let i32_instruction = instructions
            .iter()
            .copied()
            .find(|instruction| {
                let MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack { result, .. } =
                    &instruction.kind
                else {
                    unreachable!()
                };
                function.values.get(result).map(|value| &value.ty) == Some(&i32_type)
            })
            .expect("i32 ValuesUnpack instruction");
        let mut out_of_bounds = seed(i32_instruction, 3);
        eval_instruction(
            function,
            &program,
            catalog,
            &mut out_of_bounds,
            &i32_instruction.id,
            &i32_instruction.kind,
        )
        .expect("out-of-bounds ValuesUnpack symbolic execution");
        assert_eq!(
            trap_statuses(&out_of_bounds),
            vec![
                SatResult::Sat,
                SatResult::Unsat,
                SatResult::Unsat,
                SatResult::Unsat
            ],
            "OOB must stop before selected-owner, type, and clone capacity stages"
        );

        let mut wrong_tag = seed(i32_instruction, 2);
        eval_instruction(
            function,
            &program,
            catalog,
            &mut wrong_tag,
            &i32_instruction.id,
            &i32_instruction.kind,
        )
        .expect("wrong-tag ValuesUnpack symbolic execution");
        assert_eq!(
            trap_statuses(&wrong_tag),
            vec![
                SatResult::Unsat,
                SatResult::Sat,
                SatResult::Sat,
                SatResult::Unsat
            ],
            "wrong-tag must reach selected-owner and mismatch traps, but not typed clone"
        );
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn ordinary_map_owned_any_v2_rejects_mixed_and_keeps_primitive_only_on_legacy_profile() {
        let primitive_only = canonical(
            r#"
            func primitive_map() -> i32 {
                match map_new() {
                    Ok(empty) => {
                        match map_set(empty, "key", 1) {
                            Ok(one) => {
                                let count = map_size(one)
                                drop(one)
                                drop(empty)
                                count
                            },
                            Err(status) => {
                                drop(empty)
                                status
                            },
                        }
                    },
                    Err(status) => { status },
                }
            }
            func main() -> i32 { 0 }
            "#,
        );
        assert!(primitive_only.functions().values().all(|function| {
            !function
                .ownership
                .has_checker_ordinary_map_owned_any_v2_actions()
        }));
        assert!(
            !primitive_only.type_catalog().iter().any(|(_, descriptor)| {
                matches!(
                    descriptor.kind,
                    crate::core::mir::types::MirTypeKind::OrdinaryMapOwnedAnyV2
                        | crate::core::mir::types::MirTypeKind::OrdinaryMapOwnedAnyV2Payload
                        | crate::core::mir::types::MirTypeKind::OrdinaryMapOwnedAnyV2Values
                        | crate::core::mir::types::MirTypeKind::OrdinaryMapOwnedAnyV2ValuesElement
                )
            })
        );

        let source = r#"
            type Label { text: string }

            func record_map() -> i32 {
                let label = Label { text: "selected" }
                match map_new() {
                    Ok(empty) => {
                        match map_set(empty, "record", label) {
                            Ok(one) => {
                                let snapshot = values(one)
                                let count = snapshot.len()
                                drop(snapshot)
                                drop(one)
                                drop(empty)
                                drop(label)
                                count
                            },
                            Err(status) => {
                                drop(empty)
                                drop(label)
                                status
                            },
                        }
                    },
                    Err(status) => {
                        drop(label)
                        status
                    },
                }
            }

            func primitive_map() -> i32 {
                match map_new() {
                    Ok(empty) => {
                        match map_set(empty, "number", 1) {
                            Ok(one) => {
                                let count = map_size(one)
                                drop(one)
                                drop(empty)
                                count
                            },
                            Err(status) => {
                                drop(empty)
                                status
                            },
                        }
                    },
                    Err(status) => { status },
                }
            }

            func main() -> i32 { 0 }
        "#;
        let tokens = Lexer::new(source).tokenize().expect("lex mixed profile");
        let context = crate::span::SourceContext::memory(
            "verifier-tests",
            "ordinary-map-v2-mixed-profile",
            source,
        )
        .expect("register mixed profile source identity");
        let file = Parser::new_with_source_context(tokens, context)
            .parse_file()
            .expect("parse mixed profile");
        let checked = crate::core::check_program(&file).expect("Checker mixed profile");
        let rejection = match MirProgram::from_checked_program(&checked) {
            Err(errors) => format!("{errors:?}"),
            Ok(program) => format!(
                "{:?}",
                crate::verifier::validate_mir_capabilities(&program)
                    .expect_err("incomplete mixed profile must fail closed")
            ),
        };
        assert!(
            rejection.contains("coverage")
                || rejection.contains("candidate")
                || rejection.contains("profile"),
            "mixed V2 record and primitive-only callables must fail closed: {rejection}"
        );
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn managed_any_verifier_present_zero_and_missing_false_are_distinct_with_symbolic_key() {
        let program = canonical(
            r#"
            type Label { text: string }

            func observe(key: string) -> bool {
                ensures: result
                let label = Label { text: "owner-v2 profile anchor" }
                let empty = map_new()
                let anchored = map_set(empty, "anchor", label)
                let ready = map_remove(anchored, "anchor")
                let missing_pair = map_get(ready, key)
                let full = map_set(ready, key, 0)
                let found_pair = map_get(full, key)
                let missing = missing_pair.0
                let found = found_pair.0
                drop(missing_pair)
                drop(found_pair)
                drop(empty)
                drop(anchored)
                drop(ready)
                drop(full)
                drop(label)
                drop(key)
                // Presence is carried by the boolean slot; the payload stays
                // erased so a zero value cannot be mistaken for a miss.
                let present_zero = if found { 0 } else { 1 }
                found && !missing && present_zero == 0
            }
            func main() -> i32 { 0 }
        "#,
        );
        // GetAny exposes a reachable Capacity/E0800 edge. The successful
        // runtime path distinguishes a stored zero from a miss, but the
        // verifier must retain that failure counterexample.
        assert_capacity_counterexample(&program, "observe");
        let owner = program
            .functions()
            .keys()
            .find(|owner| owner.0.ends_with("observe"))
            .expect("observe owner");
        assert_eq!(
            MirReferenceInterpreter::new(&program)
                .execute(owner, &[MirRuntimeValue::String("key\0🧪值".into())])
                .expect("independent runtime result"),
            MirRuntimeValue::Bool(true)
        );
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
    fn managed_any_verifier_string_snapshot_reports_capacity_trap_before_source_drop() {
        let program = canonical(
            r#"
            func main() -> bool {
                ensures: result
                let empty = map_new()
                let full = map_set(empty, "key", "owned")
                let snapshot = map_get_string(full, "key")
                drop(empty)
                drop(full)
                let text = snapshot.unwrap()
                let equal = text == "owned"
                drop(text)
                drop(snapshot)
                equal
            }
        "#,
        );
        // The typed getter models allocator/capacity failure as a real Err
        // variant.  `unwrap` must therefore remain Disproven unless a caller
        // supplies an explicit capacity assumption; the reference success
        // path below still proves the snapshot is independent after drops.
        assert_contract(&program, "main", VerifStatus::Disproven);
        assert_eq!(
            MirReferenceInterpreter::new(&program)
                .execute(&crate::core::NodeId("function:main".into()), &[])
                .expect("snapshot survives source destruction"),
            MirRuntimeValue::Bool(true)
        );
    }

    #[test]
    #[ignore = "route-blocked: map_new Result capacity hard gate - from_checked_program rejects any map_new source with 'ordinary Map/Any owner-v2 TypeCatalog candidate has incomplete or conflicting coverage' until the per-profile routes reopen (src/core/mir/route.rs); re-migrate these sources to the nested-match Result shape when unblocking"]
